-- Módulo 62 ContratosLaborales: contratos de los empleados y sus adendas.
-- Spec: docs/specs/modulo62-contratos-laborales-backend.md (§4).

CREATE TABLE "ContratosLaborales" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "Numero" character varying(20) NOT NULL,
    "EmpleadoId" integer NOT NULL,
    "Modalidad" character varying(20) NOT NULL,
    "FechaInicio" date NOT NULL,
    "FechaFin" date,
    "SueldoBasico" numeric(12,2) NOT NULL,
    "Cargo" character varying(100) NOT NULL,
    "Estado" character varying(20) NOT NULL,
    "ContratoAnteriorId" integer,
    "FechaCierre" date,
    "MotivoCierre" character varying(300),
    CONSTRAINT "PK_ContratosLaborales" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_ContratosLaborales_Empleados_EmpleadoId" FOREIGN KEY ("EmpleadoId") REFERENCES "Empleados" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_ContratosLaborales_ContratosLaborales_ContratoAnteriorId" FOREIGN KEY ("ContratoAnteriorId") REFERENCES "ContratosLaborales" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_ContratosLaborales_SueldoBasico" CHECK ("SueldoBasico" > 0),
    CONSTRAINT "CK_ContratosLaborales_FechaFinModalidad" CHECK (("Modalidad" = 'Indeterminado') = ("FechaFin" IS NULL)),
    CONSTRAINT "CK_ContratosLaborales_FechaFin" CHECK ("FechaFin" IS NULL OR "FechaFin" > "FechaInicio")
);
CREATE UNIQUE INDEX "IX_ContratosLaborales_Numero" ON "ContratosLaborales" ("Numero");
CREATE INDEX "IX_ContratosLaborales_EmpleadoId" ON "ContratosLaborales" ("EmpleadoId");
CREATE INDEX "IX_ContratosLaborales_ContratoAnteriorId" ON "ContratosLaborales" ("ContratoAnteriorId");
-- C2: como máximo un contrato vigente por empleado; protege ante carreras (decisión 7). Incluye "Estado"
-- (constante dentro del filtro) para que el scaffold no confunda la relación con Empleados con una 1 a 1.
CREATE UNIQUE INDEX "IX_ContratosLaborales_EmpleadoId_Vigente" ON "ContratosLaborales" ("EmpleadoId", "Estado") WHERE "Estado" = 'Vigente';

CREATE TABLE "AdendasContrato" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "ContratoLaboralId" integer NOT NULL,
    "FechaVigencia" date NOT NULL,
    "Cargo" character varying(100) NOT NULL,
    "SueldoBasico" numeric(12,2) NOT NULL,
    CONSTRAINT "PK_AdendasContrato" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_AdendasContrato_ContratosLaborales_ContratoLaboralId" FOREIGN KEY ("ContratoLaboralId") REFERENCES "ContratosLaborales" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_AdendasContrato_SueldoBasico" CHECK ("SueldoBasico" > 0)
);
CREATE UNIQUE INDEX "IX_AdendasContrato_ContratoLaboralId_FechaVigencia" ON "AdendasContrato" ("ContratoLaboralId", "FechaVigencia");
